import{z as A,x as s,o as t,c as p,q as B,j as l,D as e,d as r,s as i,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"热板均匀性","description":"","frontmatter":{"title":"热板均匀性","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/hotplate-uniformity.md","filePath":"litho/hotplate-uniformity.md","lastUpdated":1791063341000}'),d={name:"litho/hotplate-uniformity.md"};function D(C,a,h,m,u,f){const o=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=B('<h1 id="热板均匀性" tabindex="-1">热板均匀性 <a class="header-anchor" href="#热板均匀性" aria-label="Permalink to &quot;热板均匀性&quot;">​</a></h1><div class="epigraph"><p>PEB 差一度，酸扩散差一截。热板地图会印到 CD 地图上，看起来像扫描仪场内剂量。</p><footer>—— 对照 PEB 热板多区控温与 CD 相关的工艺实践</footer></div><p><a href="/litho/track-scanner-link">上一课</a>要求尽快 PEB。缺口是：到了热板，温度还是 \\(T(x,y)\\)。主干 <a href="/litho/peb-bake">PEB 温度</a> 写过化学；本课写轨道热板的空间均匀与多区补偿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>多区加热、边缘散热、接近式气隙、晶圆翘曲，使 PEB 不是一个数。CAR 的 CD 对 PEB 敏感度可以到 nm/°C 量级（依胶而定）。不量热板、只调扫描剂量，会把热地图补偿进光学，换胶或换热板就全塌。</p><p><span class="marginnote">数字实例：若某胶的 PEB 敏感度是 1.5 nm/°C，热板边缘比中心冷 2°C，边缘芯片的 CD 就系统性偏 3 nm——对约 10 nm 量级的 CD 来说是三分之一以上的偏移，而且整片边缘一起偏，看起来极像镜头场内指纹。</span></p><p><span class="marginnote">常见误区：看到 CD 地图边缘异常，先去调扫描剂量。如果真凶是热板温度地图，剂量补偿会把热误差「烤」进光学模型；下次换胶或换热板，整套补偿全部作废甚至反号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>热板校准用测温晶圆或内嵌传感器，做空间图，调区功率。生产用「PEB 敏感度 × 允许 \\(\\Delta T\\)」进 CDU 预算。接近式气隙必须受控，否则均匀性随片而变。软烤硬烤同样有地图，但 PEB 通常最毒。</p>',9)),(t(),l(n,null,{default:e(()=>[i(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20HP%5B%22%E5%A4%9A%E5%8C%BA%E7%83%AD%E6%9D%BF%22%5D%20--%3E%20TXY%5B%22T(x%2Cy)%22%5D%0A%20%20TXY%20--%3E%20DIFF%5B%22%E9%85%B8%E6%89%A9%E6%95%A3%E5%9C%B0%E5%9B%BE%22%5D%0A%20%20DIFF%20--%3E%20CD%5B%22CD%20%E5%9C%B0%E5%9B%BE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"边缘场更冷是常见模态。边缘 exclusion 与 EBR 已经切掉一部分，剩下的边缘芯片仍可能吃 PEB 梯度。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"扩散长度 \\(\\propto \\sqrt{D(T)t}\\)，\\(D\\) 对 \\(T\\) 指数敏感。一度的空间差不是线性 CD 差的「一度」，而是 Arrhenius。所以热板规格用温度而不是用「看起来差不多」。",-1)),(t(),l(n,null,{default:e(()=>[i(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%221%C2%B0C%20%E7%9A%84%E6%B8%A9%E5%B7%AE%E4%BC%9A%E5%B8%A6%E6%9D%A5%E5%A4%9A%E5%A4%A7%20CD%20%E5%B7%AE%EF%BC%9F%22%5D%20--%3E%20LIN%5B%22%E7%BA%BF%E6%80%A7%E7%9B%B4%E8%A7%89%EF%BC%9A%E4%B8%80%E5%BA%A6%3D%E5%B7%AE%E4%B8%80%E7%82%B9%E7%82%B9%22%5D%0A%20%20Q%20--%3E%20AR%5B%22Arrhenius%20%E7%8E%B0%E5%AE%9E%EF%BC%9AD%20%E9%9A%8F%E6%B8%A9%E5%BA%A6%E6%8C%87%E6%95%B0%E5%8F%98%E5%8C%96%22%5D%0A%20%20AR%20--%3E%20S1%5B%22%E6%B8%A9%E5%BA%A6%E7%95%A5%E5%8D%87%EF%BC%9AD%20%E6%8C%87%E6%95%B0%E5%BC%8F%E5%8F%98%E5%A4%A7%22%5D%0A%20%20AR%20--%3E%20S2%5B%22%E6%B8%A9%E5%BA%A6%E7%95%A5%E9%99%8D%EF%BC%9AD%20%E6%8C%87%E6%95%B0%E5%BC%8F%E5%8F%98%E5%B0%8F%22%5D%0A%20%20S1%20--%3E%20L%5B%22%E6%89%A9%E6%95%A3%E9%95%BF%E5%BA%A6%E6%8C%89%20%E2%88%9A(Dt)%20%E8%B7%9F%E7%9D%80%E5%8F%98%22%5D%0A%20%20S2%20--%3E%20L%0A%20%20L%20--%3E%20CD%5B%22%E8%84%B1%E4%BF%9D%E6%8A%A4%E9%87%8F%E5%9C%B0%E5%9B%BE%20%E2%86%92%20CD%20%E5%9C%B0%E5%9B%BE%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p><span class="marginnote">术语翻译：Arrhenius（阿伦尼乌斯）规律就是「化学反应速率随温度指数式变化」的经验定律，写成 \\(D \\propto \\exp(-E_a/kT)\\)。它意味着温度误差不会按比例传给 CD，而是先被指数放大或缩小再传过去——这正是热板规格用 ±0.1°C 这类数字说话的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课轨道缺陷：热板颗粒、升华物、背面接触，与温度地图是两条账。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PEB 热板地图会伪装成光学 CDU。</li><li>多区校准进预算，不要只调剂量。</li><li>出处：PEB 课；热板工艺通识。</li></ul>',5))])}const F=A(d,[["render",D]]);export{_ as __pageData,F as default};
